from datetime import datetime
from typing import Dict, List, Optional, Any

def trigrams(text: str) -> set:
    text = text.replace('\n', ' ').replace('\t', ' ').strip()
    normalized_text = ' '.join(text.lower().split())
    if len(normalized_text) < 3:
        return set()
    trigrams = set()
    for i in range(len(normalized_text) - 2):
        trigrams.add(tuple(normalized_text[i:i+3].split()))
    return trigrams

def trigramSimilarity(text1: str, text2: str) -> float:
    if not text1 or not text2:
        return 0.0
    t1 = trigrams(text1)
    t2 = trigrams(text2)
    if not t1 or not t2:
        return 0.0
    intersection = len(t1.intersection(t2))
    union = len(t1.union(t2))
    return intersection / union if union > 0 else 0.0

def detect_duplicate(movement: Dict[str, Any], others: List[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
    # Criterio 1: Mismo monto
    # En contexto JS: Math.abs((movement.creditAmount || movement.debitAmount) - ...) < 0.01
    # En Python, asumimos que hay solo uno o el otro, o ambos pueden ser usados
    def get_amount(mvmt: Dict) -> float:
        amount = mvmt.get('creditAmount')
        if amount is not None:
            return amount
        return mvmt.get('debitAmount', 0.0)

    amount1 = get_amount(movement)

    for other in others:
        amount2 = get_amount(other)

        if amount1 is None and amount2 is None:
            continue

        if abs(amount1 - amount2) >= 0.01:
            continue

        # Criterio 2: Referencia similar o misma descripción
        sameRef = (
            movement.get('reference') is not None and
            other.get('reference') is not None and
            movement['reference'] == other['reference']
        )

        similarDesc = (
            movement.get('description') is not None and
            other.get('description') is not None and
            trigramSimilarity(movement['description'], other['description']) > 0.8
        )

        if not sameRef and not similarDesc:
            continue

        # Criterio 3: Fecha cercana (≤ 3 días calendario, implementación convencional de JS 'day')
        try:
            date1 = datetime.fromisoformat(movement['transactionDate'])
            date2 = datetime.fromisoformat(other['transactionDate'])
            daysDiff = abs((date1.date() - date2.date()).days)
        except (ValueError, AttributeError):
            daysDiff = 9999 # Error en fecha, no es dup

        if daysDiff <= 3:
            # Resultado
            confidence = 0.95 if sameRef else 0.85

            if sameRef:
                reason = f"Misma referencia y monto que movimiento del {other['transactionDate']}"
            else:
                reason = f"Descripción y monto similares a movimiento del {other['transactionDate']}"

            return {
                "isDuplicate": True,
                "originalMovementId": other['id'],
                "confidence": confidence,
                "reason": reason
            }

    return None
