def application_decision(amount, open_invoices, balance):
    credit_balance = balance.get('amount') if balance else 0 or 0

    if not open_invoices:
        if credit_balance > 0:
            return {'type': 'balance_forward', 'invoiceId': None, 
                    'details': 'Pago aplicado a saldo a favor del cliente'}
        else:
            return {'type': 'advance', 'invoiceId': None,
                    'details': 'Pago registrado como anticipo'}

    open_invoices = sorted(open_invoices, key=lambda x: x['dueDate'])
    total_open_invoices = sum(inv.get('balance', 0) for inv in open_invoices)

    if total_open_invoices == 0:
        used_balance = min(amount, credit_balance)
        if used_balance == amount:
            return {'type': 'balance_forward', 'invoiceId': None,
                    'details': 'Pago aplicado a saldo a favor del cliente'}
        else:
            return {'type': 'advance', 'invoiceId': None,
                    'details': 'Pago registrado como anticipo'}

    remaining = amount
    for invoice in open_invoices:
        inv_balance = invoice.get('balance', 0)
        if remaining <= 0:
            break

        if remaining <= inv_balance:
            if remaining == inv_balance:
                return {'type': 'full', 'invoiceId': invoice['id'],
                        'details': f'Pago completo aplicado a factura {invoice["id"]}'}
            else:
                return {'type': 'partial', 'invoiceId': invoice['id'],
                        'details': f'Pago parcial aplicado a factura {invoice["id"]}'}

        remaining -= inv_balance

    if remaining > 0:
        return {'type': 'advance', 'invoiceId': None,
                'details': 'Saldo restante aplicado como anticipo'}

    return {'type': 'advance', 'invoiceId': open_invoices[-1]['id'],
            'details': 'Factura cubierta con saldo restante'}
